const livePlatforms={twitch:{name:'Twitch',url:'https://www.twitch.tv/anderzillacwb',channel:'anderzillacwb'},youtube:{name:'YouTube',url:'https://www.youtube.com/@anderzilla-tv/live'},kick:{name:'Kick',url:'https://kick.com/anderzilla'}};
let selectedLive='twitch';
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function confirmedBroadcast(){const b=window.HUB_SETTINGS.live.broadcast;const now=Date.now();return b&&livePlatforms[b.platform]&&Date.parse(b.checkedAt)<=now&&Date.parse(b.expiresAt)>now?b:null;}
function nextBroadcast(){const cfg=window.HUB_SETTINGS.live;const candidates=[...(cfg.next?[cfg.next]:[]),...cfg.events.map(e=>({...e,title:lang==='pt'?e.titlePT:e.titleEN}))];return candidates.filter(n=>livePlatforms[n.platform]&&Date.parse(n.startsAt)>Date.now()).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt))[0]||null;}
function liveRoom(inRoom=false){const b=confirmedBroadcast(),n=nextBroadcast();if(b)selectedLive=b.platform;return `<section class="live-room" aria-labelledby="live-heading"><div class="live-summary"><img src="assets/anderzilla-ghost.png" alt="" width="54" height="54"><div class="live-heading"><p class="eyebrow"><span class="status-dot ${b?'on':''}"></span>${b?L('AO VIVO AGORA','LIVE NOW'):L('PONTO DE ENCONTRO','MEETING POINT')}</p><h2 id="live-heading">${b?escapeHTML(b.title):L('A sala de live do Ghost','Ghost’s stream room')}</h2><p>${b?escapeHTML(livePlatforms[b.platform].name):L('Status não confirmado. Escolha um canal para conferir.','Status unconfirmed. Pick a channel to check.')}</p></div>${inRoom?'':`<a class="button pink" href="#live">${L('Entrar na sala','Enter the room')} ${icon('arrow')}</a>`}</div><div class="schedule"><strong>${L('PRÓXIMA LIVE','NEXT STREAM')}</strong><span>${n?`${escapeHTML(n.title)} · ${livePlatforms[n.platform].name} · ${new Intl.DateTimeFormat(lang==='pt'?'pt-BR':'en-US',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Sao_Paulo'}).format(new Date(n.startsAt))} (${L('Brasília','Brasília time')})`:L('Agenda a confirmar. Os canais continuam a um clique.','Schedule to be confirmed. The channels are one click away.')}</span><a href="#agenda">${L("Abrir agenda →","View schedule →")}</a></div></section>`;}
function livePage(){return `<div class="wrap subpage"><p class="eyebrow">GHOST / LIVE ROOM</p><h1>${L('Puxa uma cadeira. Bora de live.','Pull up a chair. Let’s stream.')}</h1>${liveRoom(true)}<div class="live-tabs" role="group" aria-label="${L('Plataforma','Platform')}">${Object.entries(livePlatforms).map(([id,p])=>`<button class="interest" data-platform="${id}" aria-pressed="${selectedLive===id}">${p.name}</button>`).join('')}</div><div id="stream-content">${streamContent()}</div><a class="button secondary" href="#agenda">${L("Ver agenda de lives e eventos","View stream and event schedule")} →</a></div>`;}
function streamContent(){const p=livePlatforms[selectedLive];const embeddable=selectedLive==='twitch'||selectedLive==='youtube'&&/^[\w-]{11}$/.test(window.HUB_SETTINGS.live.youtubeVideoId||'');return `<div class="stream-placeholder" id="stream-frame"><img src="assets/anderzilla-ghost.png" alt="" width="85" height="85"><h2>${p.name} / AnderZilla</h2><p>${L('Assista aqui ou acompanhe pela plataforma.','Watch here or follow on the platform.')}</p>${embeddable?`<button class="button" data-load-stream>${L('Abrir player no site','Open player on site')} ▷</button>`:`<p class="stream-note">${L('Player integrado ainda não configurado para este canal.','Embedded player is not configured for this channel yet.')}</p>`}</div><div class="stream-toolbar"><a class="button secondary" href="${p.url}" target="_blank" rel="noopener noreferrer">${L('Abrir na','Open on')} ${p.name} ↗</a><p>${L('O player é da plataforma e carrega somente quando você abre. Se não reproduzir aqui, use o link direto.','The platform player loads only when you open it. If playback is unavailable here, use the direct link.')}</p></div>`;}
function loadStream(){const box=document.getElementById('stream-frame');if(!box)return;let url;if(selectedLive==='twitch'){if(box.clientWidth<400){box.innerHTML=`<p>${L('Nesta largura, assista direto na Twitch ou gire o aparelho para abrir uma janela maior.','At this width, watch directly on Twitch or rotate your device for a larger window.')}</p>`;return;}url=new URL('https://player.twitch.tv/');url.searchParams.set('channel',livePlatforms.twitch.channel);url.searchParams.set('parent',location.hostname);url.searchParams.set('autoplay','false');url.searchParams.set('muted','false');}else if(selectedLive==='youtube'&&/^[\w-]{11}$/.test(window.HUB_SETTINGS.live.youtubeVideoId||'')){url=new URL('https://www.youtube-nocookie.com/embed/'+window.HUB_SETTINGS.live.youtubeVideoId);url.searchParams.set('autoplay','0');}else return;box.classList.add('playing');box.replaceChildren();const iframe=document.createElement('iframe');iframe.src=url.href;iframe.title=`${livePlatforms[selectedLive].name} — AnderZilla`;iframe.allow='fullscreen; encrypted-media; picture-in-picture';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';box.append(iframe);}
function agendaPage(){const events=window.HUB_SETTINGS.live.events.filter(e=>livePlatforms[e.platform]&&Date.parse(e.startsAt)>Date.now()).sort((a,b)=>Date.parse(a.startsAt)-Date.parse(b.startsAt));return `<div class="wrap subpage"><p class="eyebrow">GHOST / AGENDA</p><h1>${L('Marca aí. A gente se encontra.','Save the date. See you there.')}</h1><p class="lede">${L('Lives e eventos do AnderZilla, com tema, plataforma e horário de Brasília.','AnderZilla streams and events, with topic, platform and Brasília time.')}</p><div class="agenda-list">${events.length?events.map(e=>`<article class="agenda-event"><div class="event-date"><time datetime="${escapeHTML(e.startsAt)}">${new Intl.DateTimeFormat(lang==='pt'?'pt-BR':'en-US',{day:'2-digit',month:'short',timeZone:'America/Sao_Paulo'}).format(new Date(e.startsAt))}</time></div><div><p class="eyebrow">${livePlatforms[e.platform].name} · ${new Intl.DateTimeFormat(lang==='pt'?'pt-BR':'en-US',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(new Date(e.startsAt))} / Brasília</p><h2>${escapeHTML(lang==='pt'?e.titlePT:e.titleEN)}</h2></div><a class="button secondary" href="${livePlatforms[e.platform].url}" target="_blank" rel="noopener noreferrer">${L('Abrir canal','Open channel')} ↗</a></article>`).join(''):`<section class="agenda-empty"><div class="calendar-art" aria-hidden="true"><span>GHOST</span><strong>＋</strong></div><h2>${L('O próximo encontro ainda vai ganhar data.','Our next meetup is still waiting for a date.')}</h2><p>${L('Nenhum evento anunciado por enquanto. Quando houver uma live marcada, ela aparece aqui com todos os detalhes.','No events announced yet. When a stream is scheduled, it will appear here with all the details.')}</p><a class="button pink" href="#channels">${L('Enquanto isso, conheça os canais','Meanwhile, explore the channels')} ↗</a></section>`}</div></div>`;}
function adPlacement(){return `<section class="ad-placement" aria-label="${L('Espaço publicitário demonstrativo','Demonstration advertising placement')}"><p class="eyebrow">${L('PUBLICIDADE · ESPAÇO DEMONSTRATIVO','ADVERTISEMENT · DEMONSTRATION PLACEMENT')}</p><div><strong>${L('Sua marca no radar de quem curte tecnologia.','Your brand on the radar of tech lovers.')}</strong><span>${L('Games, gadgets, IA. Com contexto, sem interromper a diversão.','Games, gadgets, AI. With context, without interrupting the fun.')}</span></div><a class="button secondary" href="#sponsor">${L('Conhecer os formatos','Explore the formats')} ↗</a></section>`;}
function affiliateArea(){const approved=window.HUB_SETTINGS.affiliates.filter(x=>x.status==='active'&&/^https:\/\//.test(x.url));const editorial=items.filter(x=>['consoles','celulares','gadgets'].includes(x.category));return `<section class="affiliate-area" aria-labelledby="affiliate-heading"><div class="heading"><div><p class="eyebrow">${L('CURADORIA & AFILIADOS','CURATION & AFFILIATES')}</p><h2 id="affiliate-heading">Loot & <span>upgrades</span></h2></div><small>${L('Escolhas para o seu universo','Choices for your universe')}</small></div><p class="affiliate-disclosure">${approved.length?L('Os links identificados como afiliados podem gerar comissão para o AnderZilla.','Links labeled affiliate may earn AnderZilla a commission.'):L('Área de afiliados em preparação. Por enquanto, os links abaixo são oficiais e não geram comissão para o AnderZilla.','Affiliate area in preparation. For now, the links below are official and do not earn AnderZilla a commission.')}</p><div class="affiliate-grid">${approved.length?approved.map(x=>`<article class="affiliate-card"><p class="eyebrow">${L('LINK DE AFILIADO','AFFILIATE LINK')}</p><h3>${escapeHTML(lang==='pt'?x.titlePT:x.titleEN)}</h3><a class="button secondary" href="${escapeHTML(x.url)}" target="_blank" rel="sponsored noopener noreferrer">${L('Ver oferta','View offer')} ↗</a></article>`).join(''):editorial.map(x=>`<article class="affiliate-card"><div class="affiliate-icon">${icon(x.category)}</div><div><p class="eyebrow">${C()[x.category]} · ${L('LINK OFICIAL','OFFICIAL LINK')}</p><h3>${title(x)}</h3><a href="${x.url}" target="_blank" rel="noopener noreferrer">${L('Conhecer na fonte','Explore at the source')} ↗</a></div></article>`).join('')}</div></section>`;}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.platform&&livePlatforms[b.dataset.platform]){selectedLive=b.dataset.platform;document.querySelectorAll('[data-platform]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.platform===selectedLive)));document.getElementById('stream-content').innerHTML=streamContent();}if(b.hasAttribute('data-load-stream'))loadStream();});
